package com.auditlog.application.service;
import com.auditlog.api.dto.ClientAccountAccessReport; import com.auditlog.application.port.HashGenerator; import com.auditlog.config.AuditHashProperties; import com.auditlog.infrastructure.persistence.entity.AuditEventEntity; import com.auditlog.infrastructure.persistence.repository.AuditEventRepository; import com.auditlog.support.exception.*; import com.auditlog.support.utility.CanonicalJsonSerializer; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class ClientAccountAccessReportService { private final AuditEventRepository events; private final AuditHashProperties hash; private final HashGenerator sha; private final CanonicalJsonSerializer canonical; private final ObjectMapper json; private final Clock clock;
 public ClientAccountAccessReportService(AuditEventRepository e,AuditHashProperties h,HashGenerator s,CanonicalJsonSerializer c,ObjectMapper j,Clock k){events=e;hash=h;sha=s;canonical=c;json=j;clock=k;}
 @Transactional(readOnly=true) public ClientAccountAccessReport report(String accountId,Instant from,Instant to){if(from!=null&&to!=null&&from.isAfter(to))throw new AuditLogException(ErrorCode.MALFORMED_REQUEST,"from must be before or equal to to"); List<ClientAccountAccessReport.AccessRecord> records=events.findByResourceTypeAndResourceIdOrderByChainSequenceAsc("ACCOUNT",accountId).stream().filter(e->from==null||!e.getRecordedAt().isBefore(from)).filter(e->to==null||!e.getRecordedAt().isAfter(to)).map(this::map).toList(); Long first=records.isEmpty()?null:records.getFirst().chainSequence(),last=records.isEmpty()?null:records.getLast().chainSequence(); String previous=records.isEmpty()?hash.genesisHash():records.getFirst().previousHash(),lastHash=records.isEmpty()?hash.genesisHash():records.getLast().contentHash(); return new ClientAccountAccessReport(accountId,from,to,Instant.now(clock),hash.genesisHash(),first,last,previous,lastHash,sha.hash(canonical.serialize(json.valueToTree(records))),records); }
 private ClientAccountAccessReport.AccessRecord map(AuditEventEntity e){return new ClientAccountAccessReport.AccessRecord(e.getEventId(),e.getChainSequence(),e.getEventType(),e.getActorId(),e.getRecordedAt(),e.getPreviousHash(),e.getContentHash(),e.getHashAlgorithm(),e.getHashVersion());}}
